import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:flutter/material.dart';
class RankingPage extends StatelessWidget{const RankingPage({super.key});@override Widget build(BuildContext c){final q=FirebaseFirestore.instance.collection('users').orderBy('orbs',descending:true).limit(100);return Scaffold(backgroundColor:const Color(0xFF050510),appBar:AppBar(title:const Text('ORQUBE RANKING'),backgroundColor:const Color(0xFF0B0B18)),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:q.snapshots(),builder:(c,s){if(s.hasError)return Center(child:Text('랭킹 오류: ${s.error}'));if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView.builder(padding:const EdgeInsets.all(12),itemCount:s.data!.docs.length,itemBuilder:(c,i){final d=s.data!.docs[i].data();return Card(color:const Color(0xFF111120),child:ListTile(leading:CircleAvatar(child:Text('${i+1}')),title:Text(d['nickname']??'ORQUBE User'),subtitle:Text('${d['rank']??'MEMBER'} · ${d['points']??0} P'),trailing:Text('${((d['orbs']??0) as num).toDouble().toStringAsFixed(4)} ORBS',style:const TextStyle(color:Color(0xFFD7FF35),fontWeight:FontWeight.bold))));});}));}}
